 def table(title,headers,rows,widths):
  nonlocal table_count
  table_count+=1;small(f'Таблица {table_count} — {title}').paragraph_format.keep_with_next=True
  t=doc.add_table(rows=1,cols=len(headers));t.autofit=False
  for c,w in zip(t.columns,widths):c.width=Cm(w)
  for c,v in zip(t.rows[0].cells,headers):c.text=str(v)
  t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
  for row in rows:
   for c,v in zip(t.add_row().cells,row):c.text=str(v)
  for row in t.rows:
   row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
   for cell in row.cells:
    mar=OxmlElement('w:tcMar')
    for side in ['top','bottom','left','right']:
     el=OxmlElement('w:'+side);el.set(qn('w:w'),'65');el.set(qn('w:type'),'dxa');mar.append(el)
    cell._tc.get_or_add_tcPr().append(mar)
    for q in cell.paragraphs:
     q.paragraph_format.first_line_indent=Cm(0);q.paragraph_format.line_spacing=1;q.paragraph_format.alignment=0
     for r in q.runs:r.font.size=Pt(12);r.bold=False
  borders=OxmlElement('w:tblBorders')
  for side in ['top','left','bottom','right','insideH','insideV']:
   el=OxmlElement('w:'+side);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'808080');borders.append(el)
  t._tbl.tblPr.append(borders);p()
